import Button from '@jetbrains/ring-ui-built/components/button/button'
import * as React from 'react'

import type {AgentId, AgentPoolId} from '../../../../../types'

type Props = {
  className?: string
  agentId: AgentId
  poolId?: AgentPoolId | null
  isCloud?: boolean
  isAuthorizeable: boolean
  showAuthorizeAgentDialog: (agentId: AgentId, poolId: AgentPoolId, isCloud: boolean) => unknown
}

function AuthorizeAgent({
  agentId,
  poolId,
  isCloud = false,
  isAuthorizeable,
  className,
  showAuthorizeAgentDialog,
}: Props) {
  const handleClick = React.useCallback(() => {
    if (poolId) {
      showAuthorizeAgentDialog(agentId, poolId, isCloud)
    }
  }, [agentId, poolId, isCloud, showAuthorizeAgentDialog])

  if (!isAuthorizeable) {
    return null
  }

  return (
    <div className={className}>
      <Button onClick={handleClick}>{'Authorize'}</Button>
    </div>
  )
}

export default React.memo(AuthorizeAgent)
